test("default function runs once per parse inside an object", () => {
  let calls = 0;
  const schema = z.object({
    a: z.string().default(() => {
      calls++;
      return "default";
    }),
  });
  expect(schema.parse({})).toEqual({ a: "default" });
  expect(calls).toBe(1);
  expect(z.string().default(() => (calls++, "x")).parse(undefined)).toBe("x");
  expect(calls).toBe(2);
});
